// Error Trigger payload → concise Slack alert.
const e = $json;
const wf = e.workflow?.name || 'unknown workflow';
const node = e.execution?.lastNodeExecuted || e.trigger?.node?.name || 'unknown node';
const msg = e.execution?.error?.message || e.trigger?.error?.message || 'no message';
const id = e.execution?.id || '';
const url = e.execution?.url || '';
const mode = e.execution?.mode || '';

const text = [
  `:rotating_light: *n8n workflow error*`,
  `Workflow: _${wf}_`,
  `Node: ${node}`,
  `Error: ${String(msg).slice(0, 500)}`,
  mode ? `Mode: ${mode}` : '',
  id ? `Execution: ${id}` : 'Trigger-level error (no execution)',
  url ? `Open: ${url}` : ''
].filter(Boolean).join('\n');

return [{ json: { text } }];
